import { useEffect, useState } from "react";
import { CLIENTID } from "../constants/SpotifyConstants";

const redirectURI = window.location.origin + '/';

interface SpotifyTokens {
    accessToken: string;
    refreshToken: string;
    expiresAt: number;
}

export function useSpotifyAuth() {
    const [tokens, setTokens] = useState<SpotifyTokens | null>(() => {
        // Initialize from localStorage (not sessionStorage!)
        const stored = localStorage.getItem('spotify_tokens');
        return stored ? JSON.parse(stored) : null;
    });
    const [profile, setProfile] = useState<any>(null);
    const [loading, setLoading] = useState(true);

    // Persist tokens to localStorage whenever they change
    useEffect(() => {
        if (tokens) {
            localStorage.setItem('spotify_tokens', JSON.stringify(tokens));
        } else {
            localStorage.removeItem('spotify_tokens');
        }
    }, [tokens]);

    useEffect(() => {
        const handleAuth = async () => {
            const params = new URLSearchParams(window.location.search);
            const code = params.get("code");

            // Check for stored tokens first
            const storedTokens = localStorage.getItem('spotify_tokens');
            const existingTokens = storedTokens ? JSON.parse(storedTokens) : null;

            if (code) {
                // Exchange code for tokens
                console.log('📝 Exchanging code for tokens...');
                try {
                    const tokenData = await getAccessToken(CLIENTID, code);
                    const expiresAt = Date.now() + tokenData.expires_in * 1000;

                    const newTokens = {
                        accessToken: tokenData.access_token,
                        refreshToken: tokenData.refresh_token,
                        expiresAt
                    };

                    setTokens(newTokens);

                    const userProfile = await fetchProfile(tokenData.access_token);
                    setProfile(userProfile);

                    // Clean up URL
                    window.history.replaceState({}, document.title, "/");
                    localStorage.removeItem("verifier");
                } catch (error) {
                    console.error('Auth error:', error);
                    localStorage.removeItem('spotify_tokens');
                } finally {
                    setLoading(false);
                }
            } else if (existingTokens) {
                // We have tokens - check if expired
                console.log('✅ Found existing tokens');
                if (Date.now() >= existingTokens.expiresAt) {
                    console.log('⏰ Token expired, refreshing...');
                    try {
                        const refreshedData = await refreshAccessToken(CLIENTID, existingTokens.refreshToken);
                        const expiresAt = Date.now() + refreshedData.expires_in * 1000;

                        const newTokens = {
                            accessToken: refreshedData.access_token,
                            refreshToken: refreshedData.refresh_token || existingTokens.refreshToken,
                            expiresAt
                        };

                        setTokens(newTokens);

                        const userProfile = await fetchProfile(refreshedData.access_token);
                        setProfile(userProfile);
                    } catch (error) {
                        console.error('Token refresh error:', error);
                        setTokens(null);
                        setProfile(null);
                        localStorage.removeItem('spotify_tokens');
                    }
                } else {
                    // Token still valid
                    console.log('✅ Token still valid, using it');
                    try {
                        setTokens(existingTokens);
                        const userProfile = await fetchProfile(existingTokens.accessToken);
                        setProfile(userProfile);
                    } catch (error) {
                        console.error('Profile fetch error:', error);
                        // Token might be invalid, clear it
                        localStorage.removeItem('spotify_tokens');
                        setTokens(null);
                    }
                }
                setLoading(false);
            } else {
                // No tokens and no code - start auth flow
                console.log('🚀 No tokens found, starting auth...');
                if (!localStorage.getItem("verifier")) {
                    await redirectToAuthCodeFlow(CLIENTID);
                } else {
                    setLoading(false);
                }
            }
        };

        handleAuth();
    }, []); // ← EMPTY ARRAY - run once on mount!

    const logout = () => {
        setTokens(null);
        setProfile(null);
        localStorage.removeItem('spotify_tokens');
        localStorage.removeItem('verifier');
        window.location.reload();
    };

    return { 
        profile, 
        loading, 
        accessToken: tokens?.accessToken || null,
        logout 
    };
}

async function redirectToAuthCodeFlow(clientId: string) {
    const verifier = generateCodeVerifier(128);
    const challenge = await generateCodeChallenge(verifier);

    localStorage.setItem("verifier", verifier); // Changed to localStorage

    const params = new URLSearchParams();
    params.append("client_id", clientId);
    params.append("response_type", "code");
    params.append("redirect_uri", redirectURI);
    params.append("scope", "user-read-private user-read-email user-read-currently-playing");
    params.append("code_challenge_method", "S256");
    params.append("code_challenge", challenge);

    window.location.href = `https://accounts.spotify.com/authorize?${params.toString()}`;
}

function generateCodeVerifier(length: number) {
    const possible = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    const values = crypto.getRandomValues(new Uint8Array(length));
    return values.reduce((acc, x) => acc + possible[x % possible.length], "");
}

async function generateCodeChallenge(codeVerifier: string) {
    const data = new TextEncoder().encode(codeVerifier);
    const digest = await window.crypto.subtle.digest('SHA-256', data);
    const bytes = new Uint8Array(digest);

    let binary = '';
    for (let i = 0; i < bytes.length; i++) {
        binary += String.fromCharCode(bytes[i]);
    }

    return btoa(binary)
        .replace(/\+/g, '-')
        .replace(/\//g, '_')
        .replace(/=+$/, '');
}

async function getAccessToken(clientId: string, code: string) {
    const verifier = localStorage.getItem("verifier"); // Changed to localStorage

    const params = new URLSearchParams();
    params.append("client_id", clientId);
    params.append("grant_type", "authorization_code");
    params.append("code", code);
    params.append("redirect_uri", redirectURI);
    params.append("code_verifier", verifier!);

    const result = await fetch("https://accounts.spotify.com/api/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: params
    });

    if (!result.ok) {
        const data = await result.json();
        throw new Error(data.error_description || 'Failed to get access token');
    }

    return await result.json();
}

async function refreshAccessToken(clientId: string, refreshToken: string) {
    const params = new URLSearchParams();
    params.append("client_id", clientId);
    params.append("grant_type", "refresh_token");
    params.append("refresh_token", refreshToken);

    const result = await fetch("https://accounts.spotify.com/api/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: params
    });

    if (!result.ok) {
        const data = await result.json();
        throw new Error(data.error_description || 'Failed to refresh token');
    }

    return await result.json();
}

async function fetchProfile(token: string) {
    const result = await fetch("https://api.spotify.com/v1/me", {
        method: "GET", 
        headers: { Authorization: `Bearer ${token}` }
    });

    if (!result.ok) {
        throw new Error('Failed to fetch profile');
    }

    return await result.json();
}
